import React, { useEffect, useRef, useState } from "react";
import { Box, Heading, Link as ChakraLink, Text } from "@chakra-ui/react";
import { Layout } from "../components/layout";
import { StaticImage } from "gatsby-plugin-image";

const matrixGlyphs = "01ABCDEFGHIJKLMNOPQRSTUVWXYZ#$%&*+-<>/\\{}[]";

const MatrixRain = ({ active }: { active: boolean }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const context = canvas?.getContext("2d");

    const disableMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce), (max-width: 600px), (hover: none)"
    ).matches;

    if (!active || !canvas || !context || disableMotion) {
      return;
    }

    const fontSize = 14;
    let canvasWidth = 0;
    let canvasHeight = 0;
    let lastFrame = 0;
    let animationFrame = 0;
    let drops: number[] = [];

    const resizeCanvas = () => {
      const bounds = canvas.getBoundingClientRect();
      const pixelRatio = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.floor(bounds.width * pixelRatio);
      canvas.height = Math.floor(bounds.height * pixelRatio);
      context.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
      canvasWidth = bounds.width;
      canvasHeight = bounds.height;
      drops = Array.from(
        { length: Math.ceil(canvasWidth / fontSize) },
        () => Math.random() * -canvasHeight / fontSize
      );
    };

    const drawFrame = (timestamp: number) => {
      animationFrame = window.requestAnimationFrame(drawFrame);
      if (timestamp - lastFrame < 55) return;
      lastFrame = timestamp;

      context.fillStyle = "rgba(7, 7, 8, 0.16)";
      context.fillRect(0, 0, canvasWidth, canvasHeight);
      context.font = `${fontSize}px monospace`;
      context.textAlign = "center";

      drops.forEach((drop, column) => {
        const glyph = matrixGlyphs[Math.floor(Math.random() * matrixGlyphs.length)];
        const x = column * fontSize + fontSize / 2;
        const y = drop * fontSize;
        context.fillStyle = column % 7 === 0
          ? "rgba(205, 55, 66, 0.92)"
          : "rgba(190, 190, 197, 0.58)";
        context.fillText(glyph, x, y);

        if (y > canvasHeight && Math.random() > 0.975) {
          drops[column] = Math.random() * -8;
        } else {
          drops[column] += 0.5 + Math.random() * 0.45;
        }
      });
    };

    resizeCanvas();
    window.addEventListener("resize", resizeCanvas);
    animationFrame = window.requestAnimationFrame(drawFrame);

    return () => {
      window.cancelAnimationFrame(animationFrame);
      window.removeEventListener("resize", resizeCanvas);
    };
  }, [active]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden="true"
      className="matrix-rain"
      style={{ opacity: active ? 0.9 : 0 }}
    />
  );
};

const IndexPage = () => {
  const [isHovered, setIsHovered] = useState(false);
  const [isFocused, setIsFocused] = useState(false);
  const isReadable = isHovered || isFocused;

  return (
    <Layout matrix>
      <Box as="main" py={{ base: 8, md: 14 }}>
        <Box
          position="relative"
          maxW="1100px"
          minH={{ base: "auto", md: "680px" }}
          mx="auto"
          overflow="hidden"
          border="1px solid"
          borderColor="#29292d"
          borderLeft="3px solid #c93442"
          borderRadius="4px"
          bg="#0b0b0d"
          boxShadow="0 24px 80px rgba(0, 0, 0, 0.38)"
          onPointerEnter={() => setIsHovered(true)}
          onPointerLeave={() => setIsHovered(false)}
          onFocusCapture={() => setIsFocused(true)}
          onBlurCapture={(event) => {
            if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
              setIsFocused(false);
            }
          }}
          tabIndex={0}
          aria-label="William Melo professional profile"
        >
          <MatrixRain active={!isReadable} />
          <Box
            className="matrix-content"
            position="relative"
            zIndex={1}
            display="grid"
            gridTemplateColumns={{ base: "1fr", md: "220px minmax(0, 1fr)" }}
            gap={{ base: 8, md: 12 }}
            alignItems="start"
            p={{ base: 6, md: 12 }}
            opacity={isReadable ? 1 : 0.2}
            transition="opacity 450ms ease"
          >
            <Box display="flex" flexDirection="column" alignItems="center" pt={2}>
              <Box
                width="180px"
                height="180px"
                flexShrink={0}
                overflow="hidden"
                borderRadius="50%"
                clipPath="circle(50%)"
                border="2px solid #a9323e"
                boxShadow="0 0 26px rgba(201, 52, 66, 0.22)"
              >
                <StaticImage
                  src="../images/me.jpg"
                  alt="William Melo"
                  width={180}
                  height={180}
                  quality={100}
                  imgStyle={{
                    borderRadius: "50%",
                    objectFit: "cover",
                    width: "180px",
                    height: "180px",
                    transform: "translateY(-10px) scale(1.06)",
                  }}
                />
              </Box>
            </Box>

            <Box minW={0}>
              <Text
                color="#c93442"
                fontSize="sm"
                fontFamily="monospace"
                letterSpacing="0.08em"
                textTransform="uppercase"
                mb={3}
              >
                Web Platforms · Conversational Flows · High-Performance Apps
              </Text>
              <Heading
                as="h1"
                color="#f0f0f1"
                fontSize={{ base: "3xl", md: "5xl" }}
                lineHeight="1.08"
                mb={6}
              >
                Senior Frontend Developer
              </Heading>
              <Text color="#f0f0f1" fontSize="lg" fontWeight="700" lineHeight="1.65">
                I build scalable, user-centric digital experiences used by
                thousands every day.
              </Text>
              <Text color="#b8b8bd" fontSize="md" lineHeight="1.8" mt={4}>
                For over 6 years, I have engineered high-performance web
                applications using Next.js and TypeScript, seamlessly
                integrated with Node.js backend services. I specialize in
                developing complex transactional journeys and robust
                conversational workflows, including enterprise WhatsApp
                integrations via Genesys Cloud, focusing on secure, accessible,
                and intuitive user interfaces.
              </Text>

              <Box mt={7}>
                <Text
                  color="#e1e1e4"
                  fontSize="sm"
                  fontWeight="700"
                  fontFamily="monospace"
                  textTransform="uppercase"
                  mb={3}
                >
                  What I care about
                </Text>
                <Box
                  as="ul"
                  display="grid"
                  gridTemplateColumns={{ base: "1fr", sm: "1fr 1fr" }}
                  gap={2}
                  pl={5}
                  color="#aaaab0"
                  fontSize="sm"
                  lineHeight="1.7"
                  sx={{ "li::marker": { color: "#c93442" } }}
                >
                  <li><strong>Clean, maintainable code:</strong> Unit testing, Git, and Agile/Scrum delivery.</li>
                  <li><strong>Enterprise-grade quality:</strong> Accessibility and security by default.</li>
                  <li><strong>Scalability:</strong> Reusable UI component architectures that help teams ship faster.</li>
                  <li><strong>User experience:</strong> Smooth, responsive web and conversational interfaces.</li>
                </Box>
              </Box>

              <Text color="#aaaab0" fontSize="sm" lineHeight="1.8" mt={6}>
                I thrive in multidisciplinary environments, bridging the gap
                between product requirements and robust engineering solutions.
              </Text>

              <Box
                mt={6}
                pt={5}
                borderTop="1px solid #2b2b30"
                display="grid"
                gridTemplateColumns={{ base: "1fr", sm: "auto 1fr" }}
                gap={2}
              >
                <Text
                  color="#c93442"
                  fontSize="xs"
                  fontFamily="monospace"
                  textTransform="uppercase"
                >
                  Core Stack
                </Text>
                <Text color="#d0d0d4" fontSize="sm" lineHeight="1.7">
                  JavaScript · TypeScript · React.js · Next.js · React Native ·
                  Node.js · Firebase · Genesys Cloud (Architect, Data Actions)
                </Text>
              </Box>

              <Text color="#96969d" fontSize="sm" lineHeight="1.8" mt={5}>
                Open to frontend and full-stack roles with international remote
                teams. Feel free to message me on{" "}
                <ChakraLink
                  href="https://www.linkedin.com/in/william-melo-dev/"
                  target="_blank"
                  rel="noopener noreferrer"
                  color="#e35a66"
                  textDecoration="underline"
                  textUnderlineOffset="3px"
                  _hover={{ color: "#ffffff" }}
                >
                  LinkedIn
                </ChakraLink>
                .
              </Text>
            </Box>
          </Box>
        </Box>
      </Box>
      <style>{`
        .matrix-rain {
          position: absolute;
          inset: 0;
          z-index: 2;
          width: 100%;
          height: 100%;
          pointer-events: none;
          transition: opacity 450ms ease;
        }

        @media (max-width: 600px), (hover: none), (prefers-reduced-motion: reduce) {
          .matrix-content {
            opacity: 1 !important;
            transition: none !important;
          }

          .matrix-rain {
            display: none;
          }
        }
      `}</style>
    </Layout>
  );
};

export default IndexPage;
